# typed: false
# frozen_string_literal: true

# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.40/engra-0.4.40-macos-arm64.tar.gz"
      sha256 "368aa8294d42b5f01fd4018577b13604673bb4fb877c3a25a1990286ac652992"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.40/engra-0.4.40-macos-x64.tar.gz"
      sha256 "745bad22ddec0d827d00563b0a92128d97966c13437492c92e7b6febe991250c"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.40/engra-0.4.40-linux-arm64.tar.gz"
      sha256 "9b641c56e9572771f14aaa44a0fd085385f28072239a0ff6a3cdf7140a2769f6"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.40/engra-0.4.40-linux-x64.tar.gz"
      sha256 "d360cfa94a3aa533af1536a057ea75093560b1e9d048e9bf767f6dc676be7fc3"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
